contracts/AttestationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title VeriForge AttestationRegistry
/// @notice On-chain registry of AI-issued RWA verification verdicts on BOT Chain.
///         Holds NO funds. Stores signed attestations so any RWA tokenization
///         project's risk verdict is publicly verifiable on-chain.
/// @dev Mainnet-safe by design: no token transfers, no payable functions,
///      verifier-set role (rotatable, no single point of failure),
///      pull-only data storage.
contract AttestationRegistry {
    /// @notice Severity of an attestation verdict.
    enum Verdict {
        BLOCKED, // 0 — critical red flags, do not touch
        CAUTION, // 1 — material findings, verify before interacting
        APPROVED // 2 — no material findings
    }

    /// @notice A single verification result for one RWA project contract.
    struct Attestation {
        address target; // RWA project contract address (token/vault/issuer)
        uint96 score; // 0-100 risk-adjusted quality score
        Verdict verdict; // BLOCKED / CAUTION / APPROVED
        uint64 findingsHash; // truncated keccak of the findings JSON (off-chain store)
        string reportUri; // URI of the full AI audit report
        bytes32 payloadHash; // keccak256 of the EXACT reviewed payload (docs + metadata + proof)
        uint64 attestedAt; // block timestamp
        uint64 blockNumber; // block where this attestation landed
    }

    /// @notice Primary verifier (compatibility pointer, part of the verifier set).
    address public verifier;

    /// @notice Full verifier set. Any member can attest. Set is rotatable:
    ///         add/remove members so no single key is a point of failure.
    mapping(address => bool) public isVerifier;
    address[] public verifierList;
    uint256 public activeVerifierCount;

    /// @notice Latest attestation per target contract.
    mapping(address => Attestation) public attestations;

    /// @notice Full attestation history per target (append-only).
    mapping(address => Attestation[]) public history;

    event Attested(
        address indexed target,
        uint96 score,
        Verdict verdict,
        uint64 findingsHash,
        string reportUri,
        bytes32 payloadHash,
        uint64 attestedAt
    );
    event VerifierAdded(address indexed v);
    event VerifierRemoved(address indexed v);

    error OnlyVerifier();
    error InvalidTarget();
    error ScoreOutOfRange();

    modifier onlyVerifier() {
        if (!isVerifier[msg.sender]) revert OnlyVerifier();
        _;
    }

    constructor(address _verifier) {
        if (_verifier == address(0)) revert InvalidTarget();
        verifier = _verifier;
        isVerifier[_verifier] = true;
        verifierList.push(_verifier);
        activeVerifierCount = 1;
    }

    /// @notice Add a verifier to the set (any existing verifier can).
    function addVerifier(address v) external onlyVerifier {
        if (v == address(0)) revert InvalidTarget();
        if (!isVerifier[v]) {
            isVerifier[v] = true;
            verifierList.push(v);
            activeVerifierCount += 1;
            emit VerifierAdded(v);
        }
    }

    /// @notice Remove a verifier from the set. A compromised key can be cut
    ///         immediately by any remaining verifier. Last verifier cannot be removed.
    function removeVerifier(address v) external onlyVerifier {
        if (v == msg.sender && activeVerifierCount <= 1) revert OnlyVerifier();
        if (isVerifier[v]) {
            isVerifier[v] = false;
            activeVerifierCount -= 1;
            if (v == verifier) verifier = address(0);
            emit VerifierRemoved(v);
        }
    }

    function verifierCount() external view returns (uint256) {
        return activeVerifierCount;
    }

    /// @notice Record a verification verdict for an RWA contract.
    /// @param target The RWA project contract that was audited.
    /// @param score 0-100 quality score (higher is safer).
    /// @param verdict BLOCKED / CAUTION / APPROVED.
    /// @param findingsHash Truncated keccak256 of the full findings payload.
    /// @param reportUri URI where the full report is stored.
    /// @param payloadHash keccak256 of the exact reviewed payload (docs +
    ///        structured asset metadata + proof URI). Binds the verdict to
    ///        immutable content: any post-attestation edit breaks the hash.
    function attest(
        address target,
        uint96 score,
        Verdict verdict,
        uint64 findingsHash,
        string calldata reportUri,
        bytes32 payloadHash
    ) external onlyVerifier returns (uint64 blockNumber) {
        if (target == address(0)) revert InvalidTarget();
        if (score > 100) revert ScoreOutOfRange();
        if (payloadHash == bytes32(0)) revert InvalidTarget();

        uint64 ts = uint64(block.timestamp);
        uint64 blk = uint64(block.number);

        Attestation memory a = Attestation({
            target: target,
            score: score,
            verdict: verdict,
            findingsHash: findingsHash,
            reportUri: reportUri,
            payloadHash: payloadHash,
            attestedAt: ts,
            blockNumber: blk
        });

        attestations[target] = a;
        history[target].push(a);

        emit Attested(target, score, verdict, findingsHash, reportUri, payloadHash, ts);
        return blk;
    }

    /// @notice Read the latest attestation for a target.
    function getAttestation(address target) external view returns (Attestation memory) {
        return attestations[target];
    }

    /// @notice Read the full attestation history for a target.
    function getHistory(address target) external view returns (Attestation[] memory) {
        return history[target];
    }
}

contracts/IssuanceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {AttestationRegistry} from "./AttestationRegistry.sol";

/// @title IssuanceRegistry
/// @notice On-chain catalog of tokenized RWA issuances on BOT Chain.
///         The AI compliance gate is enforced HERE: an issuance can only be
///         listed if its RwaToken carries an APPROVED attestation from the
///         verifier set (the VeriForge AI backend). Refuses unapproved issuances.
///         Holds no funds. Only the verifier can list.
contract IssuanceRegistry {
    /// @notice A listed issuance.
    struct Issuance {
        uint64 id;
        address issuer; // who deploys + sells units
        address token; // RwaToken (units)
        address distributor; // RevenueDistributor (revenue share pool)
        uint256 pricePerToken; // USDT 6dp per 1e18 unit
        string docsUri; // issuer documentation reviewed by the AI gate
        bytes32 payloadHash; // commitment to the exact reviewed payload (docs + metadata + proof)
        uint64 listedAt;
        uint64 blockNumber;
    }

    AttestationRegistry public immutable attestations;
    address public verifier;

    Issuance[] private _issuances;
    mapping(address => uint64) private _tokenToId; // token -> id+1 (0 = not listed)

    event Issued(
        uint64 indexed id,
        address indexed issuer,
        address indexed token,
        address distributor,
        uint256 pricePerToken,
        string docsUri,
        bytes32 payloadHash
    );
    event VerifierChanged(address indexed oldVerifier, address indexed newVerifier);

    error OnlyVerifier();
    error NotApproved();
    error AlreadyListed();
    error ZeroAddress();
    error InvalidPrice();
    error InvalidPayload();

    modifier onlyVerifier() {
        if (msg.sender != verifier) revert OnlyVerifier();
        _;
    }

    constructor(address verifier_, address attestations_) {
        if (verifier_ == address(0) || attestations_ == address(0)) revert ZeroAddress();
        verifier = verifier_;
        attestations = AttestationRegistry(attestations_);
    }

    /// @notice List a new issuance. Reverts unless the token carries an
    ///         APPROVED attestation — the on-chain enforcement of the AI gate.
    /// @param issuer_ Owner selling units.
    /// @param token RwaToken address.
    /// @param distributor RevenueDistributor address.
    /// @param pricePerToken USDT 6dp per 1e18 unit.
    /// @param docsUri Documentation reviewed by the AI compliance gate.
    /// @param payloadHash Commitment to the exact reviewed payload. Must match
    ///        the hash the verifier attested, or the listing is refused.
    function issue(
        address issuer_,
        address token,
        address distributor,
        uint256 pricePerToken,
        string calldata docsUri,
        bytes32 payloadHash
    ) external onlyVerifier returns (uint64 id) {
        if (issuer_ == address(0) || token == address(0) || distributor == address(0)) revert ZeroAddress();
        if (pricePerToken == 0) revert InvalidPrice();
        if (_tokenToId[token] != 0) revert AlreadyListed();

        // ── THE AI GATE, enforced on-chain ──────────────────────────────
        // AttestationRegistry only lets verifier-set members write, and only
        // stores verdicts the AI backend produced. No APPROVED attestation
        // with a matching payload commitment => no listing.
        AttestationRegistry.Attestation memory a = attestations.getAttestation(token);
        if (a.verdict != AttestationRegistry.Verdict.APPROVED) revert NotApproved();
        if (a.payloadHash != payloadHash) revert InvalidPayload();

        id = uint64(_issuances.length) + 1;
        _issuances.push(Issuance({
            id: id,
            issuer: issuer_,
            token: token,
            distributor: distributor,
            pricePerToken: pricePerToken,
            docsUri: docsUri,
            payloadHash: payloadHash,
            listedAt: uint64(block.timestamp),
            blockNumber: uint64(block.number)
        }));
        _tokenToId[token] = id;

        emit Issued(id, issuer_, token, distributor, pricePerToken, docsUri, payloadHash);
    }

    function setVerifier(address newVerifier) external onlyVerifier {
        if (newVerifier == address(0)) revert ZeroAddress();
        emit VerifierChanged(verifier, newVerifier);
        verifier = newVerifier;
    }

    function count() external view returns (uint64) {
        return uint64(_issuances.length);
    }

    function getIssuance(uint64 id) external view returns (Issuance memory) {
        return _issuances[id - 1];
    }

    function getIssuanceByToken(address token) external view returns (Issuance memory) {
        uint64 id = _tokenToId[token];
        if (id == 0) revert ZeroAddress();
        return _issuances[id - 1];
    }

    function getAll() external view returns (Issuance[] memory) {
        return _issuances;
    }
}

